from flask import Flask, jsonify, request
from flask_cors import CORS
import os, base64
from datetime import datetime

app = Flask(__name__)
CORS(app)
orders = []

_HTML_B64 = ""
HTML = base64.b64decode(_HTML_B64).decode("utf-8")

@app.route("/")
def index():
    return HTML, 200, {"Content-Type": "text/html; charset=utf-8"}

@app.route("/health")
def health():
    return jsonify({"status": "ok", "service": "saota-venture"})

@app.route("/api/book", methods=["POST"])
def book():
    data = request.get_json() or {}
    for field in ["name", "phone", "address"]:
        if not data.get(field, "").strip():
            return jsonify({"success": False, "error": f"{field} is required."}), 400
    oid = f"SAO{len(orders)+1001}"
    order = {
        "id": oid, "name": data["name"].strip(),
        "phone": data["phone"].strip(), "email": data.get("email","").strip(),
        "service": data.get("service","").strip(), "capacity": data.get("capacity","").strip(),
        "address": data["address"].strip(), "area": data.get("area","").strip(),
        "notes": data.get("notes","").strip(), "status": "pending",
        "created": datetime.utcnow().isoformat()
    }
    orders.append(order)
    print(f"[ORDER] {order}")
    return jsonify({"success": True, "message": f"Order received! Booking ID: {oid}. We will call you within 30 minutes.", "order_id": oid})

@app.route("/api/contact", methods=["POST"])
def contact():
    data = request.get_json() or {}
    name = data.get("name","").strip()
    msg  = data.get("message","").strip()
    if not name or not msg:
        return jsonify({"success": False, "error": "Name and message required."}), 400
    print(f"[CONTACT] {name}: {msg}")
    return jsonify({"success": True, "message": "Message received! We will respond within 24 hours."})

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 5000))
    app.run(host="0.0.0.0", port=port, debug=False)
